SELECT s.*, CASE WHEN EXISTS ( SELECT 1 FROM inspect_record r WHERE r.station_id = s.id AND r.plan_project_id = #{planProjectId} AND r.status = 1 ) THEN 1 ELSE 0 END AS status FROM station s WHERE s.project_id = #{projectId}
AND (s.owner_name LIKE CONCAT('%', #{keyword}, '%') OR s.station_code LIKE CONCAT('%', #{keyword}, '%'))
AND EXISTS ( SELECT 1 FROM inspect_record r WHERE r.station_id = s.id AND r.plan_project_id = #{planProjectId} AND r.status = 1 )
AND NOT EXISTS ( SELECT 1 FROM inspect_record r WHERE r.station_id = s.id AND r.plan_project_id = #{planProjectId} AND r.status = 1 )
ORDER BY s.station_code ASC LIMIT #{offset}, #{limit}

SELECT s.*, 0 AS status FROM station s WHERE s.project_id = #{projectId}
AND (s.owner_name LIKE CONCAT('%', #{keyword}, '%') OR s.station_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.station_code ASC LIMIT #{offset}, #{limit}
